+});
+
+test('GET skips malformed entries', async ({ request }) => {
+  const good = { id: '1', text: 'ok', done: false };
+  await writeFile(
+    TODOS_FILE,
+    JSON.stringify([good, { id: 2, text: 'bad', done: false }, { id: '3', text: 'x' }, null]),
+  );
+  expect(await (await request.get('/api/todos')).json()).toEqual([good]);
+});

